\documentclass[border=10pt]{standalone}
\usepackage{pgfplots}
\pgfplotsset{compat=1.18}
\usepgfplotslibrary{colormaps}

\begin{document}
\begin{tikzpicture}
\begin{axis}[
    view={45}{25},
    xlabel=$x$,
    ylabel=$y$,
    zlabel=$z$,
    title={Hyperboloid of One Sheet: $4x^2 - 16y^2 + z^2 = 16$},
    domain=-4:4,
    y domain=-3:3,
    samples=40,
    samples y=40,
    colormap/viridis,
    width=12cm,
    height=10cm,
    grid=major,
    ]
    % Plot upper half (y >= 0)
    \addplot3[surf, opacity=0.7, shader=interp] 
        ({x}, {sqrt((4*x^2 + y^2 - 16)/16)}, {y});

    % Plot lower half (y <= 0)
    \addplot3[surf, opacity=0.7, shader=interp] 
        ({x}, {-sqrt((4*x^2 + y^2 - 16)/16)}, {y});
\end{axis}
\end{tikzpicture}
\end{document}

