    \addplot[red, thick, domain=-4:-2.01] {sqrt((x^2-4)/4)};
    \addplot[red, thick, domain=-4:-2.01] {-sqrt((x^2-4)/4)};
    \addplot[red, thick, domain=2.01:4] {sqrt((x^2-4)/4)};
    \addplot[red, thick, domain=2.01:4] {-sqrt((x^2-4)/4)};
